  Future<void> addHabit() async {final a=TextEditingController(),b=TextEditingController();bool quit=false;final ok=await showDialog<bool>(context:context,builder:(x)=>StatefulBuilder(builder:(x,setL)=>Directionality(textDirection:TextDirection.rtl,child:AlertDialog(title:const Text('عادة جديدة'),content:Column(mainAxisSize:MainAxisSize.min,children:[SegmentedButton<bool>(segments:const [ButtonSegment(value:false,label:Text('أبني')),ButtonSegment(value:true,label:Text('أترك'))],selected:{quit},onSelectionChanged:(s)=>setL(()=>quit=s.first)),const SizedBox(height:10),TextField(controller:a,decoration:const InputDecoration(labelText:'اسم العادة')),const SizedBox(height:10),TextField(controller:b,decoration:InputDecoration(labelText:quit?'السلوك البديل':'كيف تجعلها سهلة؟'))]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('حفظ'))]))));if(ok==true&&a.text.trim().isNotEmpty){data.habits.add(HabitItem(id:uid(),name:a.text.trim(),quit:quit,replacement:b.text.trim()));changed(3);}}
