  Future<void> review() async {final a=TextEditingController(text:data.todayWin),b=TextEditingController(text:data.todayLesson),d=TextEditingController(text:data.tomorrowFocus);final ok=await showDialog<bool>(context:context,builder:(x)=>Directionality(textDirection:TextDirection.rtl,child:AlertDialog(title:Text('محاسبة اليوم — $score%'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:a,decoration:const InputDecoration(labelText:'أهم انتصار')),const SizedBox(height:8),TextField(controller:b,decoration:const InputDecoration(labelText:'أين قصّرت؟ وما الدرس؟')),const SizedBox(height:8),TextField(controller:d,decoration:const InputDecoration(labelText:'أهم تركيز للغد'))])),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('لاحقاً')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('احفظ محاسبتي'))])));if(ok==true){data.todayWin=a.text.trim();data.todayLesson=b.text.trim();data.tomorrowFocus=d.text.trim();changed(10);await ask('هذه مراجعتي اليوم: انتصاري ${data.todayWin}، درسي ${data.todayLesson}، وتركيزي غداً ${data.tomorrowFocus}. أعطني ملاحظة قصيرة.');}}
}
